<?php
require dirname(__DIR__).'/includes/bootstrap.php';
$emp=(string)($_GET['emp']??'');$person=Database::q('SELECT * FROM employees WHERE emp_no=?',[$emp])->fetch();
if(!$person)http_response_code(404);
$active='employees';$pageTitle='Employee details';
if(!$person){require BASE_PATH.'/includes/header.php';echo '<h1>Employee not found</h1><p><a href="employees.php">Back to employees</a></p>';require BASE_PATH.'/includes/footer.php';exit;}
$period=in_array($_GET['period']??'',['month','year','all'],true)?$_GET['period']:'month';
$from=$period==='month'?date('Y-m-01'):($period==='year'?date('Y-01-01'):'1000-01-01');$to=date('Y-m-d');
$status=in_array($_GET['status']??'',['present','late','half','review'],true)?$_GET['status']:'';
$view=($_GET['view']??'cards')==='list'?'list':'cards';$order=($_GET['order']??'desc')==='asc'?'asc':'desc';
$link=static fn($changes=[])=>'?'.http_build_query(array_merge(['emp'=>$emp,'period'=>$period,'status'=>$status,'view'=>$view,'order'=>$order],$changes));
$params=[$emp,$from,$to];$where='emp_no=? AND work_date BETWEEN ? AND ?';
$stats=Database::q('SELECT COUNT(*) days,COALESCE(SUM(work_minutes),0) worked,COALESCE(SUM(overtime_minutes),0) overtime,COALESCE(SUM(late_minutes>0),0) late FROM attendance WHERE '.$where,$params)->fetch();
if($status==='review')$where.=' AND (review_required=1 OR check_out IS NULL)';elseif($status!==''){$where.=' AND status=?';$params[]=$status;}
$total=(int)Database::q('SELECT COUNT(*) FROM attendance WHERE '.$where,$params)->fetchColumn();
$pages=max(1,(int)ceil($total/9));$page=max(1,min($pages,(int)($_GET['page']??1)));
$rows=Database::q('SELECT * FROM attendance WHERE '.$where.' ORDER BY work_date '.strtoupper($order).' LIMIT 9 OFFSET '.(($page-1)*9),$params)->fetchAll();
$profile=EmployeeProfile::get($emp);
$shift=Shift::forEmployee($emp,date('Y-m-d'));
require BASE_PATH.'/includes/header.php';
?>
<p><a href="employees.php">← Employee directory</a></p>
<section class="employee-profile">
<div class="profile-toolbar"><h1>Employee details</h1><form method="get" class="profile-period"><input type="hidden" name="emp" value="<?= e($emp) ?>"><label for="profile-period">Period</label><select id="profile-period" name="period"><?php foreach(['month'=>'This month','year'=>'This year','all'=>'All time'] as $key=>$label): ?><option value="<?= $key ?>" <?= $period===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button class="btn ghost">Apply</button></form><?php if(Auth::role()!=='viewer'): ?><a class="btn" data-edit-panel href="employee-edit.php?emp=<?= e(rawurlencode($emp)) ?>">Edit employee</a><?php endif; ?></div>
<div class="profile-person"><?= EmployeePhoto::avatar($person) ?><div class="profile-person-body"><div class="profile-name"><h2><?= e($person['name']) ?></h2><?= status_label(!empty($profile['archived_at'])?'Archived':($person['active']?'Active':'Inactive')) ?></div>
<dl class="profile-facts"><div><dt>Employee number</dt><dd><?= e($emp) ?></dd></div><div><dt>Department</dt><dd><?= e($person['department']?:'Not added') ?></dd></div><div><dt>Current shift</dt><dd><?= e($shift['name']??'No shift assigned') ?></dd></div><div><dt>Working hours</dt><dd><?= $shift?e(substr($shift['start_time'],0,5).' – '.substr($shift['end_time'],0,5)):'—' ?></dd></div><div><dt>Card number</dt><dd><?= e($person['card_no']?:'Not added') ?></dd></div><div><dt>Device sync</dt><dd><?= status_label(EmployeeSync::state($person)) ?></dd></div></dl><dl class="profile-facts"><?php foreach(EmployeeProfile::FIELDS as $key=>$label): ?><div><dt><?= e($label) ?></dt><dd><?= e($profile[$key]??'Not added') ?></dd></div><?php endforeach; ?></dl></div></div>
<div class="profile-metrics"><div><strong><?= (int)$stats['days'] ?></strong><span>Recorded days</span></div><div><strong><?= Attendance::fmtMinutes((int)$stats['worked']) ?></strong><span>Total worked</span></div><div><strong><?= Attendance::fmtMinutes((int)$stats['overtime']) ?></strong><span>Calculated overtime</span></div><div><strong><?= (int)$stats['late'] ?></strong><span>Late arrivals</span></div></div>
<p class="profile-period-note">Totals for <?= $period==='all'?'all recorded dates':e(date('d M Y',strtotime($from)).' – '.date('d M Y',strtotime($to))) ?>. Only recorded attendance is included.</p>
</section>
<section class="profile-attendance">
<div class="profile-toolbar"><h2>Attendance history</h2><a class="btn ghost" href="attendance-calendar.php?emp=<?= e(rawurlencode($emp)) ?>">Calendar</a><nav class="view-tabs" aria-label="Attendance layout"><a href="<?= e($link(['view'=>'cards'])) ?>" <?= $view==='cards'?'aria-current="page"':'' ?>>Cards</a><a href="<?= e($link(['view'=>'list'])) ?>" <?= $view==='list'?'aria-current="page"':'' ?>>List</a></nav><a class="btn ghost" href="<?= e($link(['order'=>$order==='desc'?'asc':'desc'])) ?>"><?= $order==='desc'?'Newest first ↓':'Oldest first ↑' ?></a><button type="button" class="btn ghost" id="profile-filter-toggle" aria-expanded="<?= $status!==''?'true':'false' ?>" aria-controls="profile-filters">Filters<?= $status!==''?' •':'' ?></button></div>
<form method="get" id="profile-filters" class="filters" <?= $status===''?'hidden':'' ?>><input type="hidden" name="emp" value="<?= e($emp) ?>"><input type="hidden" name="period" value="<?= e($period) ?>"><input type="hidden" name="view" value="<?= e($view) ?>"><input type="hidden" name="order" value="<?= e($order) ?>"><label>Status<select name="status"><?php foreach([''=>'All statuses','present'=>'Present','late'=>'Late','half'=>'Half day','review'=>'Needs review'] as $key=>$label): ?><option value="<?= $key ?>" <?= $status===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><button class="btn">Apply filters</button><a href="<?= e($link(['status'=>''])) ?>">Clear</a></form>
<p class="muted"><?= $total ?> records<?= $status!==''?' · Filtered results':'' ?></p>
<?php if(!$rows): ?><div class="profile-empty"><h3>No attendance in this view</h3><p>Choose another period or clear the status filter to see more records.</p><a href="<?= e($link(['period'=>'all','status'=>''])) ?>">View all attendance</a></div><?php endif; ?>
<div class="profile-history <?= $view==='list'?'profile-history-list':'' ?>">
<?php foreach($rows as $r): $state=$r['check_out']?(!empty($r['review_required'])?'Review punches':$r['status']):Report::checkoutState($r); ?>
<article class="profile-day"><div class="profile-day-heading"><a data-attendance-panel href="attendance-detail.php?<?= e(http_build_query(['emp'=>$emp,'day'=>$r['work_date']])) ?>"><?= e(date('d M Y',strtotime($r['work_date']))) ?></a><?= status_label($state) ?></div><dl class="profile-day-times"><div><dt>Check in</dt><dd><?= $r['check_in']?e(date('H:i',strtotime($r['check_in']))):'—' ?></dd></div><div><dt>Check out</dt><dd><?= $r['check_out']?e(date('H:i',strtotime($r['check_out']))):'—' ?><?= $r['check_out'] && substr($r['check_out'],0,10)!==$r['work_date']?' (+1 day)':'' ?></dd></div></dl><div class="profile-day-footer"><span>Worked <strong><?= Attendance::fmtMinutes((int)$r['work_minutes']) ?></strong></span><span>OT <strong><?= Attendance::fmtMinutes((int)$r['overtime_minutes']) ?></strong></span></div></article>
<?php endforeach; ?></div>
<?php if($pages>1): ?><nav class="profile-pagination" aria-label="Attendance pages"><?php if($page>1): ?><a class="btn ghost" href="<?= e($link(['page'=>$page-1])) ?>">Previous</a><?php endif; ?><span>Page <?= $page ?> of <?= $pages ?></span><?php if($page<$pages): ?><a class="btn ghost" href="<?= e($link(['page'=>$page+1])) ?>">Next</a><?php endif; ?></nav><?php endif; ?>
</section>
<script>document.getElementById('profile-filter-toggle').addEventListener('click',function(){const panel=document.getElementById('profile-filters');panel.hidden=!panel.hidden;this.setAttribute('aria-expanded',String(!panel.hidden));});</script>
<details class="action-disclosure employee-history"><summary>Shift assignment history</summary><?php foreach(Database::q('SELECT * FROM shift_assignments WHERE emp_no=? ORDER BY effective_date DESC,id DESC',[$emp])->fetchAll() as $assignment): $sh=json_decode($assignment['snapshot'],true); ?><p><?= $assignment['effective_date']==='1000-01-01'?'Initial available baseline':e($assignment['effective_date']) ?> · <?= e($sh['name']??'No shift') ?> · <?= e($sh['start_time']??'') ?>–<?= e($sh['end_time']??'') ?></p><?php endforeach; ?>
</details><details class="action-disclosure employee-history"><summary>Leave history</summary><?php $leave=Database::q('SELECT * FROM leaves WHERE emp_no=? ORDER BY start_date DESC LIMIT 30',[$emp])->fetchAll();if(!$leave): ?><p>No leave recorded.</p><?php endif; foreach($leave as $l): ?><p><?= e($l['start_date']) ?> to <?= e($l['end_date']) ?> · <?= status_label(Leave::TYPES[$l['type']]??$l['type']) ?></p><?php endforeach; ?>
</details><details class="action-disclosure employee-history"><summary>Correction history</summary><?php $corrections=Database::q('SELECT * FROM attendance_corrections WHERE emp_no=? ORDER BY id DESC LIMIT 30',[$emp])->fetchAll();if(!$corrections): ?><p>No corrections recorded.</p><?php endif;foreach($corrections as $c): ?><p><?= e($c['work_date']) ?> · <?= status_label($c['approval_status']) ?> · <?= e($c['reason']) ?> · <?= e($c['reviewed_by']??'Awaiting review') ?></p><?php endforeach; ?>
</details><?php require BASE_PATH.'/includes/footer.php'; ?>
